export function monsterTypeName(mnum, female = false) {
    const genderedNames = GENDERED_MONSTER_NAMES.get(mnum);
    if (genderedNames) return genderedNames[female ? 1 : 0];
    return MONSTER_NAME[mnum] || 'monster';
}

// C ref: mondata.h nonliving().  Symbol numbers use the generated S_* order.
const M2_UNDEAD = 0x00000002;
const PM_MANES = 50;
const S_VORTEX = 22;
const S_GOLEM = 55;

export function monsterIsNonliving(mnum) {
    return !!((MONSTER_FLAGS2[mnum] ?? 0) & M2_UNDEAD)
        || mnum === PM_MANES
        || MONSTER_SYMBOL[mnum] === S_VORTEX
        || MONSTER_SYMBOL[mnum] === S_GOLEM;
}

